auto prepare_joints()
{
    frog::geo::Container<Joint> joints_(10000);
    for (auto[i, j] : JOINTS)
        joints_.push(j);
    return joints_;
}

template<typename C>
auto do_stuff(C collisions, const frog::geo::Container<Joint>& joints_)
    -> std::vector<unsigned>
{
    collisions.reset();

    for (auto info : COLLISIONS)
        collisions.insert_collision(std::move(info));

    collisions.update(joints_);

    auto collided_screws = std::vector<unsigned>{};
    collided_screws.reserve(SCREWS.size());

    using frog::geo::idx_t;

    for (auto[screw_a, screw_b] : SCREWS)
    {
        auto data = std::vector<idx_t>{ screw_a, screw_b };

        bool collided = false;
        for (const auto& info : collisions.first())
        {
            auto [idx_a, idx_b] = info;

            auto included = [&](const auto& idx) -> bool
            {
                return idx == idx_a || idx == idx_b;
            };

            if (std::ranges::any_of(data, included)
                && not std::ranges::all_of(data, included))
            {
                collided = true;
                break;
            }
        }

        collided_screws.push_back(collided);
    }

    return collided_screws;
}


static void ColllisionsSet(benchmark::State& state)
{
    auto joints_ = prepare_joints();
    for (auto _ : state)
    {
        auto ret = do_stuff( frog::geo::Collisions<std::set>(), joints_ );
        benchmark::DoNotOptimize(ret);
    }
}


