static void ColllisionsBag(benchmark::State& state)
{
    auto joints_ = prepare_joints();
    for (auto _ : state)
    {
        auto ret = do_stuff( frog::geo::Collisions<frog::geo::CollisionBag>(), joints_ );
        benchmark::DoNotOptimize(ret);
    }
}

BENCHMARK(ColllisionsSet);
